#[cfg(test)]
mod tests {
    use std::{collections::HashSet, fs, path::Path};

    use super::*;

    #[test]
    fn trim_material_catalog_is_complete_ordered_and_unique() {
        assert_eq!(VANILLA_TRIM_MATERIAL_DESCRIPTORS.len(), 11);
        let mut resources = HashSet::new();
        for (index, entry) in VANILLA_TRIM_MATERIAL_DESCRIPTORS.iter().enumerate() {
            assert_eq!(entry.material.vanilla_registry_index(), index);
            assert!(resources.insert(entry.resource_id));
            assert!(entry.resource_id.starts_with("minecraft:"));
            assert!(entry.description_color <= 0xFF_FF_FF);
        }
    }

    #[test]
    fn trim_material_catalog_preserves_vanilla_mappings() {
        assert_eq!(
            VanillaTrimMaterialIdentity::for_vanilla_registry_id(0),
            Some(VanillaTrimMaterialIdentity::Quartz)
        );
        assert_eq!(
            VanillaTrimMaterialIdentity::for_vanilla_registry_id(10),
            Some(VanillaTrimMaterialIdentity::Resin)
        );
        assert_eq!(
            VanillaTrimMaterialIdentity::for_vanilla_registry_id(-1),
            None
        );
        assert_eq!(
            VanillaTrimMaterialIdentity::for_vanilla_registry_id(11),
            None
        );
        assert_eq!(
            VanillaTrimMaterialIdentity::for_resource_id("minecraft:iron"),
            Some(VanillaTrimMaterialIdentity::Iron)
        );
        assert_eq!(
            VanillaTrimMaterialIdentity::for_resource_id("example:custom_trim"),
            None
        );
        assert_eq!(
            VanillaTrimMaterialIdentity::Iron.resource_id(),
            "minecraft:iron"
        );
        assert_eq!(
            VanillaTrimMaterialIdentity::Iron.description_color(),
            0xEC_EC_EC
        );
        assert_eq!(
            VanillaTrimMaterialIdentity::Resin.description_color(),
            0xFC_78_12
        );
    }

    #[test]
    fn production_sources_do_not_redeclare_trim_material_catalog_facts() {
        fn visit(directory: &Path, violations: &mut Vec<String>) {
            for entry in fs::read_dir(directory).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    visit(&path, violations);
                    continue;
                }
                if path.extension().and_then(|value| value.to_str()) != Some("rs") {
                    continue;
                }
                let display = path.to_string_lossy();
                if display.ends_with("/trim_materials.rs")
                    || display.ends_with("/tests.rs")
                    || display.contains("/tests/")
                {
                    continue;
                }
                let source = fs::read_to_string(&path).unwrap();
                if source.contains("enum VanillaTrimMaterialIdentity")
                    || source.contains("struct VanillaTrimMaterial {")
                    || source.contains("const VANILLA_TRIM_MATERIALS")
                    || source.contains("fn vanilla_trim_material_resource_id(")
                {
                    violations.push(display.to_string());
                }
            }
        }
        let mut violations = Vec::new();
        visit(
            Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap(),
            &mut violations,
        );
        assert!(
            violations.is_empty(),
            "parallel trim-material catalog owners: {violations:?}"
        );
    }
}
